import { useState } from "react";

function Form() {
  const [text, setText] = useState("");
  const addItem = () => {};
  return (
    <form id="item-form">
      <div className="form-control">
        <input
          type="text"
          className="form-input"
          id="item-input"
          name="item"
          placeholder="Enter Item"
          onChange={addItem}
        />
      </div>
      <div className="form-control">
        <button type="submit" className="btn">
          <i className="fa-solid fa-plus"></i> Add Item
        </button>
      </div>
    </form>
  );
}

export default Form;
